mapper.select:
select fin_float_calc_rule_detail.LEV lev, fin_float_calc_rule_detail.base_rule_id baseRuleId, fin_float_calc_rule_detail.coefficient , fin_float_calc_rule_detail.spread_rate * 100 spreadRate, fin_float_calc_rule_detail.charge_ratio * 100 chargeRatio from fin_float_calc_rule_detail ,fin_product,fin_cash_info left join FIN_TRADE_PRODUCT on fin_cash_info.finprod_id = FIN_TRADE_PRODUCT.finprod_id AND fin_cash_info.BRANCH = FIN_TRADE_PRODUCT.BRANCH where fin_float_calc_rule_detail.cash_id = fin_cash_info.cash_id and fin_cash_info.finprod_id = fin_product.finprod_id and fin_cash_info.cash_type_1 = #{cashType1} and fin_cash_info.cash_type_2 = #{cashType2} and fin_float_calc_rule_detail.EFF_DATE = ( select max(t.EFF_DATE) from fin_float_calc_rule_detail t where t.CASH_ID = fin_float_calc_rule_detail.CASH_ID AND T.EFF_DATE <= STR_TO_DATE(#{effDate},'%Y-%m-%d') )
and fin_cash_info.finprod_id = #{periodProdId}
and FIN_TRADE_PRODUCT.PERIOD_ID = #{periodId}
and fin_cash_info.BRANCH = 0
and fin_cash_info.finprod_type = #{type01}

mapper.sql:
select t.* from( select '待处理' validStatus, t.periodProdId, t.periodId, cast(t.investCycle as char) investCycle, t.publish_type publishType, t.rateType, t.rateLower, t.rateLimit, t.rate, t.indexId, t.coefficient, t.spreadRate, t.resetType, t.termType, t.baseRule, t.dates startDate, t.dates + t.investCycle endDate, t.p_finprod_id as finprodId, 0 branch from ( select fp.finprod_id periodProdId, '' periodId, fpa.investment_cycle investCycle, fbri.publish_type, fbri.rate_type rateType, fbri.rate_lower *100 rateLower, fbri.rate_limit *100 rateLimit, fbri.rate *100 rate, fbri.index_id indexId, fbri.coefficient, fbri.spread_rate *100 spreadRate, fbri.reset_type resetType, fpa.term_type termType, case when fbri.publish_type = #{publishType01} then CONCAT_ws('', cast(fbri.rate_lower *100 as decimal(4,7)) , '~', cast(fbri.rate_limit *100 decimal(4,7))) when fbri.rate_type = #{calcType01} then cast(fbri.rate * 100 as decimal(4,7)) when fbri.rate_type = #{calcType02} then CONCAT_ws('', fbri.index_id ,'*', fbri.coefficient ,'+',cast(fbri.spread_rate*100 as decimal(4,7))) end as baseRule, fp.p_finprod_id, fp.mdate, days.dates from fin_product fp left join fin_product_add fpa on fp.finprod_id = fpa.finprod_id
inner join PTL_PORTFOLIO_AUTHORITY ppa on fpa.PORTFOLIO_ID = ppa.PORTFOLIO_ID and ppa.USER_ID = #{userId}
left join fin_open_plan fop on fp.p_finprod_id = fop.finprod_id left join fin_base_rule_info fbri on fbri.finprod_id = fp.finprod_id,( select t.GDATE as dates from ( select DATE_ADD(t.startDate, INTERVAL @rownum DAY) GDATE, @rownum := @rownum + 1 AS rownum, days from (select * from (SELECT STR_TO_DATE(#{platDate}, '%Y-%m-%d') startDate, 7 days FROM dual) su, (SELECT @rownum := 0) r) t left join connect_by_key cbk on cbk.num <= t.days ) t where t.rownum <= t.days+1
) days where fpa.deal_mode = #{dealMode10} and fbri.eff_date = ( select max(t.eff_date) from fin_base_rule_info t where t.base_rule_id = fbri.base_rule_id and t.branch = 0 and t.eff_date <= STR_TO_DATE(#{platDate},'%Y-%m-%d') ) and fp.p_finprod_id is not null and fop.finprod_id is null and fbri.base_rule_type = #{baseRuleType01}
and fpa.term_type != #{termType03}
)t where t.dates <= t.mdate and not exists (select t1.finprod_id from fin_trade_product t1 where t1.finprod_id = t.periodProdId and t1.term = t.investCycle and t1.vdate = t.dates)) t
and t.finprodId in
#{item}
and t.startDate >= STR_TO_DATE(#{startDateBegin},'%Y-%m-%d')
and t.startDate <= STR_TO_DATE(#{startDateEnd},'%Y-%m-%d')
and t.endDate >= STR_TO_DATE(#{endDateBegin},'%Y-%m-%d')
and t.endDate <= STR_TO_DATE(#{endDateEnd},'%Y-%m-%d')
union all select '待处理' validStatus, t.periodProdId, t.periodId, cast(t.investCycle as char) investCycle, t.publishType, t.rateType, t.rateLower, t.rateLimit, t.rate, t.indexId, t.coefficient, t.spreadRate, t.resetType, t.termType, t.baseRule, t.startDate, t.endDate, t.p_finprod_id as finprodId, 0 branch from( select fp.finprod_id periodProdId, '' periodId, fpa.investment_cycle investCycle, fop.open_vdate startDate, fop.open_vdate + fpa.investment_cycle endDate, fbri.publish_type publishType, fbri.rate_type rateType, fbri.rate_lower *100 rateLower, fbri.rate_limit *100 rateLimit, fbri.rate *100 rate, fbri.index_id indexId, fbri.coefficient, fbri.spread_rate *100 spreadRate, fbri.reset_type resetType, fpa.term_type termType, case when fbri.publish_type = #{publishType01} then CONCAT_ws(cast('', fbri.rate_lower *100 as decimal(4,7)) , '~' , cast(fbri.rate_limit *100 as decimal(4,7))) when fbri.rate_type = #{calcType01} then cast(fbri.rate * 100 as decimal(4,7)) when fbri.rate_type = #{calcType02} then CONCAT_ws('', fbri.index_id ,'*', fbri.coefficient,'+', cast(fbri.spread_rate*100 as decimal(4,7))) end as baseRule, fp.p_finprod_id from fin_product fp left join fin_product_add fpa on fp.finprod_id = fpa.finprod_id
inner join PTL_PORTFOLIO_AUTHORITY ppa on fpa.PORTFOLIO_ID = ppa.PORTFOLIO_ID and ppa.USER_ID = #{userId}
left join fin_open_plan fop on fp.p_finprod_id = fop.finprod_id left join fin_base_rule_info fbri on fbri.finprod_id = fp.finprod_id where fpa.deal_mode = #{dealMode10} and fbri.eff_date = ( select max(t.eff_date) from fin_base_rule_info t where t.base_rule_id = fbri.base_rule_id and t.branch = 0 and t.eff_date <= STR_TO_DATE(#{platDate},'%Y-%m-%d') ) and fp.p_finprod_id is not null and not exists ( select t.finprod_id from fin_trade_product t where t.finprod_id = fpa.finprod_id and t.term = fpa.investment_cycle and t.vdate = fop.open_vdate ) and fop.open_vdate >= STR_TO_DATE(#{platDate},'%Y-%m-%d') and fop.open_vdate <= STR_TO_DATE(#{platDate},'%Y-%m-%d') + 7 and fbri.base_rule_type = #{baseRuleType01}
and fpa.term_type != #{termType03}
) t
and t.p_finprod_id in
#{item}
and t.startDate >= STR_TO_DATE(#{startDateBegin},'%Y-%m-%d')
and t.startDate <= STR_TO_DATE(#{startDateEnd},'%Y-%m-%d')
and t.endDate >= STR_TO_DATE(#{endDateBegin},'%Y-%m-%d')
and t.endDate <= STR_TO_DATE(#{endDateEnd},'%Y-%m-%d')
